# Demo: horizontal and vertical rays extend from matching edge markers.
# Top row columns define vertical rays; side markers extend to those columns.
# transform(grid) is the task program.

def _demo_check():
    d = [[0,0,0,0,0,6,5,3,0,0,0,0,0,0,0]] + [[0]*15 for _ in range(14)]
    d[2][14] = 3
    d[4][0] = 6
    o = transform(d)
    assert o[1][5:8] == [6,5,3]
    assert o[2][8:] == [3]*7
    assert o[4][:7] == [6]*6 + [5]
    assert all(o[r][6] == 5 for r in range(5,15))
    return True

def _test_result():
    g = [[0,0,0,4,8,5,0,0,0,0,0]] + [[0]*11 for _ in range(10)]
    g[7][0] = 4
    g[9][10] = 5
    return transform(g)

if __name__ == '__main__':
    assert _demo_check()
    print(_test_result())
